import os, json, csv
from collections import defaultdict

DATA_BASE = "storage/shared/agency_lab/data"
ANAL_BASE = "storage/shared/agency_lab/analyses"
CSV_DIR = os.path.join(ANAL_BASE, "csv")
os.makedirs(ANAL_BASE, exist_ok=True)
os.makedirs(CSV_DIR, exist_ok=True)

# -------- Loader (dict/list-aware) with lineage and timestamp handling --------
def find_export_files():
    files = []
    top = os.path.join("storage/shared/agency_lab", "axiom_rng_actions_v1_2b_interactions.json")
    if os.path.exists(top):
        files.append(top)
    for root, _, fnames in os.walk(DATA_BASE):
        for fn in fnames:
            if fn.endswith(".json"):
                files.append(os.path.join(root, fn))
    return files

def infer_lineage_from_path(path):
    p = path.replace("\\", "/").split("/")
    if "lineage_exports" in p:
        i = p.index("lineage_exports")
        if i + 1 < len(p):
            seg = p[i+1]
            if seg.endswith("_exports"):
                return seg[: -len("_exports")].rstrip("_").lower()
    return None

def infer_lineage_from_agent(agent_id):
    s = str(agent_id) if agent_id is not None else ""
    for sep in ["_", " "]:
        if sep in s and s.split(sep)[0]:
            return s.split(sep)[0].lower().rstrip("_")
    return (s.lower().rstrip("_") if s else "unknown")

def coerce_actions_payload(payload):
    # Returns (actions_list, payload_lineage)
    if isinstance(payload, dict):
        acts = payload.get("actions")
        if isinstance(acts, list):
            return acts, payload.get("lineage")
        for k in ("data", "items"):
            v = payload.get(k)
            if isinstance(v, list):
                return v, payload.get("lineage")
        return ([payload], payload.get("lineage"))
    elif isinstance(payload, list):
        return payload, None
    else:
        return [], None

def load_actions():
    actions = []
    files = find_export_files()
    for path in files:
        try:
            with open(path, "r", encoding="utf-8") as f:
                payload = json.load(f)
        except Exception:
            continue
        acts, payload_lineage = coerce_actions_payload(payload)
        path_lineage = infer_lineage_from_path(path)
        for a in acts:
            if not isinstance(a, dict):
                continue
            agent_id = a.get("agent_id") or a.get("agent") or a.get("source_agent")
            action_type = a.get("action_type") or a.get("type")
            if not agent_id or not action_type:
                continue
            tick = a.get("tick")
            try:
                tick = int(tick) if tick is not None else None
            except Exception:
                tick = None
            ts = a.get("timestamp")
            target = a.get("target")
            if target is not None:
                target = str(target)
            lineage = (
                a.get("lineage")
                or payload_lineage
                or path_lineage
                or infer_lineage_from_agent(agent_id)
                or "unknown"
            )
            actions.append({
                "agent_id": str(agent_id),
                "action_type": str(action_type),
                "tick": tick,
                "timestamp": ts,
                "target": target,
                "lineage": str(lineage).lower(),
                "src": path,
            })
    return actions

# -------- Core metrics (combined/per-lineage/per-agent) --------
def compute_base_metrics(actions):
    if not actions:
        return {
            "combined": {"agents": 0, "actions": 0, "unique_types": 0,
                         "persistence_mean": 0.0, "emergence_mean": 0.0, "collab_mean": 0.0},
            "per_lineage": [], "per_agent": [],
            "counts": {"total_actions": 0, "total_interactions": 0, "total_agents": 0, "total_unique_types": 0},
        }
    agents = sorted({a["agent_id"] for a in actions})
    agent_set = set(agents)
    per_agent = {}
    persistent_types = {"create", "build", "generate", "store", "initialize", "save", "write"}
    global_types = set(a["action_type"] for a in actions if a.get("action_type"))

    for a in actions:
        ag = per_agent.setdefault(a["agent_id"], {
            "lineage": a["lineage"], "actions": 0, "persistent": 0, "unique_types": set(), "interactions": 0,
        })
        ag["actions"] += 1
        t = a["action_type"]; ag["unique_types"].add(t)
        if t in persistent_types:
            ag["persistent"] += 1

    for a in actions:
        tgt = a.get("target")
        if tgt and tgt in agent_set:
            per_agent[a["agent_id"]]["interactions"] += 1

    per_agent_metrics = []
    total_actions = 0
    total_interactions = 0
    for agent, st in per_agent.items():
        actions_n = st["actions"]; total_actions += actions_n; total_interactions += st["interactions"]
        pr = (st["persistent"] / actions_n) if actions_n > 0 else 0.0
        es = (len(st["unique_types"]) / max(1, len(global_types)))
        ci = (st["interactions"] / (2 * actions_n)) if actions_n > 0 else 0.0
        per_agent_metrics.append({
            "agent_id": agent, "lineage": st["lineage"], "actions": actions_n,
            "unique_types": len(st["unique_types"]), "persistence_rate": pr,
            "emergence_score": es, "collaboration_index": ci,
        })

    if per_agent_metrics:
        p_mean = sum(x["persistence_rate"] for x in per_agent_metrics) / len(per_agent_metrics)
        e_mean = sum(x["emergence_score"] for x in per_agent_metrics) / len(per_agent_metrics)
        c_mean = sum(x["collaboration_index"] for x in per_agent_metrics) / len(per_agent_metrics)
    else:
        p_mean = e_mean = c_mean = 0.0

    lineage_groups = defaultdict(list)
    for x in per_agent_metrics:
        lineage_groups[x["lineage"]].append(x)

    per_lineage = []
    for lin, items in sorted(lineage_groups.items()):
        if not items: continue
        agents_cnt = len(items)
        actions_sum = sum(i["actions"] for i in items)
        uniq_types = sum(i["unique_types"] for i in items)
        p_lin = sum(i["persistence_rate"] for i in items) / agents_cnt
        e_lin = sum(i["emergence_score"] for i in items) / agents_cnt
        c_lin = sum(i["collaboration_index"] for i in items) / agents_cnt
        per_lineage.append({
            "lineage": lin, "agents": len(items), "actions": actions_sum, "unique_types": uniq_types,
            "persistence_mean": p_lin, "emergence_mean": e_lin, "collab_mean": c_lin,
        })

    combined = {
        "agents": len(per_agent_metrics), "actions": total_actions, "unique_types": len(global_types),
        "persistence_mean": p_mean, "emergence_mean": e_mean, "collab_mean": c_mean,
    }

    return {
        "combined": combined, "per_lineage": per_lineage, "per_agent": per_agent_metrics,
        "counts": {"total_actions": total_actions, "total_interactions": total_interactions,
                   "total_agents": len(per_agent_metrics), "total_unique_types": len(global_types)},
    }

# -------- Cross-lineage graph metrics --------
def compute_graph_metrics(actions):
    # Map agent_id -> lineage
    agent_lineage = {}
    for a in actions:
        agent_lineage[a["agent_id"]] = a["lineage"]
    agent_set = set(agent_lineage.keys())

    # Adjacency counts between lineages
    adj = defaultdict(lambda: defaultdict(int))
    for a in actions:
        tgt = a.get("target")
        if tgt and tgt in agent_set:
            src_lin = agent_lineage.get(a["agent_id"], "unknown")
            tgt_lin = agent_lineage.get(tgt, "unknown")
            adj[src_lin][tgt_lin] += 1

    # Degree metrics
    lineages = sorted(set(list(adj.keys()) + [l for v in adj.values() for l in v.keys()]))
    indeg = {lin: 0 for lin in lineages}
    outdeg = {lin: 0 for lin in lineages}
    for s in lineages:
        outdeg[s] = sum(adj[s].values()) if s in adj else 0
    for s in adj:
        for t, w in adj[s].items():
            indeg[t] = indeg.get(t, 0) + w

    # Reciprocity: for each unordered pair (a,b), check both directions
    reciprocal_edges = 0
    total_pairs = 0
    seen_pairs = set()
    for a_lin in lineages:
        for b_lin in lineages:
            if a_lin >= b_lin:  # avoid duplicates and self-pairs
                continue
            w_ab = adj[a_lin].get(b_lin, 0)
            w_ba = adj[b_lin].get(a_lin, 0)
            if w_ab > 0 or w_ba > 0:
                total_pairs += 1
                if w_ab > 0 and w_ba > 0:
                    reciprocal_edges += 1
    reciprocity = (reciprocity := (reciprocal_edges / total_pairs)) if total_pairs > 0 else 0.0

    return {
        "adjacency": {s: dict(adj[s]) for s in adj},
        "in_degree": indeg,
        "out_degree": outdeg,
        "reciprocity": reciprocity,
    }

# -------- Rolling window metrics by lineage (W=5, step=2) --------
def rolling_by_lineage(actions, W=5, step=2):
    # Only use actions with tick present
    acts = [a for a in actions if a.get("tick") is not None]
    if not acts:
        return []
    min_t = min(a["tick"] for a in acts)
    max_t = max(a["tick"] for a in acts)
    persistent_types = {"create", "build", "generate", "store", "initialize", "save", "write"}

    rows = []
    t = min_t
    while t <= max_t:
        start = t
        end = t + W - 1
        window = [a for a in acts if start <= a["tick"] <= end]
        if window:
            by_lin = defaultdict(list)
            for a in window:
                by_lin[a["lineage"]].append(a)
            for lin, lst in by_lin.items():
                actions_n = len(lst)
                if actions_n == 0:
                    pr = ci = 0.0
                else:
                    pers = sum(1 for a in lst if a["action_type"] in persistent_types)
                    # interactions where target is known agent in window's agent set
                    agent_ids_win = {a["agent_id"] for a in window}
                    inter = sum(1 for a in lst if a.get("target") in agent_ids_win)
                    pr = pers / actions_n
                    ci = inter / (2 * actions_n)
                rows.append([lin, start, end, actions_n, f"{pr:.6f}", f"{ci:.6f}"])
        t += step
    return rows

# -------- Save utilities --------
def save_json(path, obj):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2)

def save_txt_v2_5(path, base_metrics, graph_metrics, roll_rows):
    lines = []
    c = base_metrics["combined"]
    lines.append("JOINT METRICS v2.5 — Multi-lineage (persistence refinements + graph + rolling)")
    lines.append(f"combined\tagents={c['agents']}\tactions={c['actions']}\tunique_types={c['unique_types']}\t"
                 f"persistence_mean={c['persistence_mean']:.6f}\temergence_mean={c['emergence_mean']:.6f}\t"
                 f"collab_mean={c['collab_mean']:.6f}")
    lines.append("")
    lines.append("Per-lineage summary:")
    lines.append("lineage\tagents\tactions\tunique_types\tpersistence_mean\temergence_mean\tcollab_mean")
    for row in base_metrics["per_lineage"]:
        lines.append(f"{row['lineage']}\t{row['agents']}\t{row['actions']}\t{row['unique_types']}\t"
                     f"{row['persistence_mean']:.6f}\t{row['emergence_mean']:.6f}\t{row['collab_mean']:.6f}")
    lines.append("")
    lines.append("Graph summary:")
    lines.append(f"reciprocity\t{graph_metrics['reciprocity']:.6f}")
    lines.append("in_degree:")
    for lin, v in sorted(graph_metrics["in_degree"].items()):
        lines.append(f"{lin}\t{v}")
    lines.append("out_degree:")
    for lin, v in sorted(graph_metrics["out_degree"].items()):
        lines.append(f"{lin}\t{v}")
    lines.append("")
    lines.append("Rolling (W=5, step=2) by lineage:")
    lines.append("lineage\tstart\tend\tactions\tpersistence_rate\tcollaboration_index")
    for r in roll_rows:
        lines.append("\t".join(map(str, r)))
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")

def main():
    actions = load_actions()
    base = compute_base_metrics(actions)
    graph = compute_graph_metrics(actions)
    roll = rolling_by_lineage(actions, W=5, step=2)

    out_json = os.path.join(ANAL_BASE, "joint_metrics_v2_5.json")
    out_txt = os.path.join(ANAL_BASE, "joint_metrics_v2_5.txt")
    save_json(out_json, {"base": base, "graph": graph, "rolling": roll})
    save_txt_v2_5(out_txt, base, graph, roll)

    # CSVs
    # Graph adjacency
    adj_csv = os.path.join(CSV_DIR, "joint_metrics_v2_5_adjacency.csv")
    with open(adj_csv, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["source_lineage","target_lineage","weight"])
        for s, d in graph["adjacency"].items():
            for t, wgt in d.items():
                w.writerow([s, t, wgt])
    # Rolling per-lineage
    roll_csv = os.path.join(CSV_DIR, "joint_metrics_v2_5_per_lineage_rolling.csv")
    with open(roll_csv, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["lineage","start","end","actions","persistence_rate","collaboration_index"])
        for r in roll:
            w.writerow(r)

    print("V2_5_DONE", out_txt, adj_csv, roll_csv, "SOURCES", len(actions))
    return 0

if __name__ == "__main__":
    import sys
    try:
        sys.exit(main())
    except Exception as e:
        print("ERROR", str(e))
        sys.exit(1)
